// Pilih periode dashboard pusat: ?bulan=YYYY-MM (default bulan berjalan WITA) → id file "Data Omzet Harian <tahun>" dari tab config master.
// Output 1 item: {bulan, tahun, doc, tab_data, zona, hari_ini, gagal:[], catatan:[]}
const baca = node => { for (const n of [node, 1, 2, 3, 4, 5].map((x, i) => i ? node + x : node)) { try { return $(n).all().map(it => it.json); } catch (e) {} } return null; };
const gagal = [], catatan = [];
const cfgRows = baca('Baca Config');
if (cfgRows === null || cfgRows.some(x => x && x.error)) gagal.push('Baca Config');
const cfg = {};
for (const r of cfgRows || []) { const k = String(r.key ?? r.Key ?? '').trim(); if (k) cfg[k] = r.value ?? r.Value ?? ''; }
const zona = String(cfg.zona || 'Asia/Makassar');
const now = DateTime.now().setZone(zona);
const wh = (baca('Webhook Monitoring Pusat') || [{}])[0] || {};
const q = wh.query || {};
let bulan = String(q.bulan || '').trim();
if (!/^\d{4}-(0[1-9]|1[0-2])$/.test(bulan)) { if (bulan) catatan.push('Parameter bulan "' + bulan + '" tidak valid (format YYYY-MM), memakai bulan berjalan'); bulan = now.toFormat('yyyy-MM'); }
const tahun = +bulan.slice(0, 4);
const doc = String(cfg['data_file_' + tahun] || '').trim();
if (!doc) catatan.push('config data_file_' + tahun + ' belum diisi di tab config master');
return [{ json: { bulan, tahun, doc: doc || 'BELUM-DIISI', ada_doc: !!doc, tab_data: String(cfg.tab_data || 'data'), zona,
  hari_ini: now.toISODate(), sekarang: now.toISO({ suppressMilliseconds: true }), gagal, catatan } }];

// Susun Monitoring Pusat: target vs omzet per minggu per outlet, peringkat mingguan + akumulasi bulan, channel per outlet & brand.
// Sumber: Rekap Omzet (Master) tab outlet/target/target_channel + "Data Omzet Harian <tahun>" tab data (difilter ke bulan diminta).
// omzet harian = kolom omzet (Tunai + QRIS + Ojol, tanpa ongkir) hasil flow Sinkron Kasir. Kosong = belum diisi (bukan 0).
// Minggu: M1 1–7, M2 8–14, M3 15–21, M4 22–akhir. Target progres = target bulanan × bobot kumulatif. Bobot dibaca per outlet dari tab target
// (bobot_m1..m4, beda tiap bulan: Jul 28/24/22/26, Agu 26/26/24/24, Sep 24/28/27/21, Okt/Nov 27/27/23/23); 27/27/23/23% hanya cadangan bila kosong (+catatan).
// Channel kasir (tab ChannelHarian → ch_offline/ch_whatsapp/ch_ojol) hanya dihitung di hari yang diisi; cakupan = hari diisi ÷ hari ber-omzet.
// Online admin (tab OnlineHarian → ch_organik/ch_ads/ch_live): hari admin isi → Online Organik + Online Ads + Live Shopping; hari admin belum isi → WhatsApp kasir
// masuk "Online (belum dipisah)". Mix per outlet = Offline + Organik + Ads + Live Shopping + Online belum dipisah + Ojol.
// Target brand dibanding langsung: Offline→Takeaway Outlet, Organik→Online Organik, Ads→Online Ads, Live→Live Shopping, Ojol→Ojol (kolom Ojol closing kasir).
// Kolom ch_live opsional: bila belum ada di Data Omzet Harian, Live Shopping = belum terbaca (bukan 0). CRM tidak terukur. % capaian hanya tampil bila cakupan hari = 100%.
// Output 1 item (format sama dengan flow Oktober + tambahan ranking, channel, channel_brand).
const BOBOT_DEFAULT = [0.27, 0.27, 0.23, 0.23];
const OUTLET_DEFAULT = [['SPO','Sungai Poso'],['GWA','Gowa'],['SDG','Sudiang'],['BRB','Barombong'],['LMB','Limbung'],['PRE','Pare-Pare'],['TML','Tamalate']];
