  const O = Object.fromEntries(outl.map(o => [o.kode, Object.assign(o, { target_bulanan: null, target_per_minggu: [null, null, null, null],
    realisasi_per_minggu: [null, null, null, null], hari_terisi: [0, 0, 0, 0], tgl_terakhir: null, hari: {},
    ch: { offline: 0, whatsapp: 0, ojol: 0, organik: 0, ads: 0, live: 0, online_kasir: 0, omzet_hari_isi: 0, hari_isi: 0, hari_admin: 0, hari_admin_tanpa_kasir: 0, selisih: 0, hari_beda: 0, selisih_online: 0, hari_beda_online: 0,
      per_minggu: [0, 1, 2, 3].map(() => ({ offline: 0, whatsapp: 0, ojol: 0, organik: 0, ads: 0, live: 0, online_kasir: 0, hari_isi: 0, hari_admin: 0 })) },
    ojol_kasir: null, verif: 0, bobot: null })]));
