    o.realisasi_per_minggu[w] = (o.realisasi_per_minggu[w] || 0) + omzet; o.hari_terisi[w]++;
    o.tgl_terakhir = Math.max(o.tgl_terakhir || 0, d); tglTerakhir = Math.max(tglTerakhir, d);
    const oj = num(r.ojol); if (oj !== null) o.ojol_kasir = (o.ojol_kasir || 0) + oj;
