    const cv = ['ch_offline', 'ch_whatsapp', 'ch_ojol'].map(f => num(r[f])), av = ['ch_organik', 'ch_ads', 'ch_live'].map(f => num(r[f]));
    const C = o.ch, pm = C.per_minggu[w], isiK = cv.some(x => x !== null), isiA = av.some(x => x !== null);
    if (isiK) {
      const [a, b, c] = cv.map(x => x || 0);
      C.offline += a; C.whatsapp += b; C.ojol += c; C.hari_isi++; C.omzet_hari_isi += omzet;
      pm.offline += a; pm.whatsapp += b; pm.ojol += c; pm.hari_isi++;
      if (!isiA) { C.online_kasir += b; pm.online_kasir += b; }
      const kas = num(r.total_kaspin) ?? omzet, sel = num(r.ch_selisih) ?? (a + b + c - kas);
      C.selisih += sel; if (Math.abs(sel) > 0.5) C.hari_beda++;
    }
    if (isiA) {
      const [g, d, l] = av.map(x => x || 0);
      C.organik += g; C.ads += d; C.live += l; C.hari_admin++; pm.organik += g; pm.ads += d; pm.live += l; pm.hari_admin++;
      if (isiK) { const so = num(r.ch_selisih_online) ?? (g + d + l - (cv[1] || 0)); C.selisih_online += so; if (Math.abs(so) > 0.5) C.hari_beda_online++; } else C.hari_admin_tanpa_kasir++;
    }
  }
  if (luarOutlet.size) catatan.push('Kode outlet di data tapi tidak ada di tab outlet: ' + [...luarOutlet].join(', '));
  if (!nBaris && dataRows !== null) catatan.push('Belum ada omzet ' + bulan + ' di sheet pusat (jalankan flow Sinkron Kasir)');
  // minggu pelaporan (sama dengan flow Oktober): minggu terakhir lengkap; minggu sesudahnya = berjalan (prorata hari)
  let minggu = 0, mb = null;
