if (typeof $ === 'function') {
  const baca = node => { for (const n of [node, 1, 2, 3, 4, 5].map((x, i) => i ? node + x : node)) { try { return $(n).all().map(it => it.json); } catch (e) {} } return null; };
  const P = (baca('Pilih Periode') || [{}])[0] || {};
  const gagal = [].concat(P.gagal || []), catatan = [].concat(P.catatan || []);
  const rowsOf = node => { const r = baca(node); if (r === null || r.some(x => x && x.error)) { gagal.push(node); return null; } return r.filter(x => x && Object.keys(x).some(k => k !== 'row_number')); };
  const inp = { P, gagal, catatan, outletRows: rowsOf('Baca Outlet'), targetRows: rowsOf('Baca Target'), tcRows: rowsOf('Baca Target Channel'),
    dataRows: P.ada_doc === false ? (catatan.push('File data tahun ' + P.tahun + ' belum ada'), null) : rowsOf('Baca Data') };
  if (!P.bulan) return [{ json: { ok: false, message: 'Periode tidak terbaca (Baca Config gagal?)', gagal, catatan } }];
  if (gagal.includes('Baca Config')) return [{ json: { ok: false, message: 'Tab config Rekap Omzet (Master) tidak terbaca (cek akses Service Account)', bulan: P.bulan, gagal, catatan } }];
  if (inp.dataRows === null) return [{ json: { ok: false, message: 'Data omzet sheet pusat tidak terbaca (cek akses Service Account ke file Data Omzet Harian ' + P.tahun + ')', bulan: P.bulan, gagal, catatan } }];
  return [{ json: susun(inp) }];
